head.b:skin:
/* Blogger chrome off — shop fills the page */
#navbar,#navbar-iframe,.navbar,.blog-pager,.post-footer,#comments,.footer-outer,.header-outer,.tabs-outer,.sidebar-wrapper,#Attribution1,.Attribution,#page{display:none!important}
body{margin:0;padding:0!important;min-width:0!important;background:#f3eee4}
.content-outer,.content-inner,.main-inner,.region-inner,.columns{width:auto!important;max-width:none!important;min-width:0!important;padding:0!important;margin:0!important;background:transparent!important;box-shadow:none!important}

:root{
  --bg:#f3eee4;--fg:#1c1610;--surface:#faf7f1;--surface-muted:#ece4d6;
  --muted:#6e6458;--subtle:#8a8074;--primary:#b5522a;--primary-fg:#fffaf3;
  --accent:#2c2118;--accent-fg:#faf7f1;--border:#e0d4c4;--hero:#efe6d6;
  --shadow:0 0 0 1px rgba(28,22,16,.06),0 1px 2px -1px rgba(28,22,16,.06),0 2px 4px 0 rgba(28,22,16,.04);
  --shadow-hover:0 0 0 1px rgba(28,22,16,.1),0 1px 2px -1px rgba(28,22,16,.08),0 2px 4px 0 rgba(28,22,16,.06);
  --display:"Fraunces","Iowan Old Style",Palatino,serif;
  --sans:"Figtree","Segoe UI",system-ui,sans-serif;
}
*{box-sizing:border-box}
html{-webkit-font-smoothing:antialiased;background:var(--bg);color:var(--fg)}
html,body{margin:0;padding:0!important;min-width:0!important;max-width:none!important}
body{font-family:var(--sans);background:var(--bg);color:var(--fg);line-height:1.5;min-height:100dvh}
img{max-width:100%;display:block}
button,a.btn,[role=button]{cursor:pointer;font:inherit}
button:disabled{cursor:default}
h1,h2,h3{text-wrap:balance;margin:0}
p{text-wrap:pretty}
a{color:inherit}
.media{outline:1px solid rgba(28,22,16,.1);outline-offset:-1px}
.wrap{width:min(72rem,calc(100% - 2rem));margin-inline:auto}
@media(min-width:640px){.wrap{width:min(72rem,calc(100% - 3rem))}}
.skip{position:absolute;left:-999px}
.skip:focus{left:12px;top:12px;z-index:80;background:var(--surface);padding:.5rem 1rem;border-radius:999px}
header.bar{position:sticky;top:0;z-index:40;border-bottom:1px solid color-mix(in srgb,var(--border) 80%,transparent);background:color-mix(in srgb,var(--bg) 90%,transparent);backdrop-filter:blur(12px)}
.bar-inner{display:flex;align-items:center;justify-content:space-between;gap:.75rem;height:4rem}
@media(min-width:640px){.bar-inner{height:4.5rem}}
.brand{display:flex;align-items:center;gap:.75rem;min-width:0;text-decoration:none}
.brand img{width:40px;height:40px;border-radius:6px;object-fit:cover}
.brand strong{display:block;font-family:var(--display);font-weight:500;font-size:1.05rem;letter-spacing:-.02em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.brand small{display:none;color:var(--muted);font-size:.75rem}
@media(min-width:640px){.brand small{display:block}}
nav.desk{display:none;gap:1.5rem}
@media(min-width:1024px){nav.desk{display:flex}}
nav.desk a{color:var(--muted);text-decoration:none;font-size:.9rem}
nav.desk a:hover{color:var(--fg)}
.bar-actions{display:flex;align-items:center;gap:.5rem}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.4rem;border:0;border-radius:999px;padding:.7rem 1.1rem;text-decoration:none;font-weight:500;font-size:.9rem;line-height:1;transition:transform .12s ease,background .15s ease}
.btn svg{width:16px;height:16px;flex:none}
.btn-lg{padding:.9rem 1.25rem;font-size:1rem}
.btn-primary{background:var(--primary);color:var(--primary-fg)}
.btn-primary:hover{background:#9d4624}
.btn-outline{background:transparent;color:var(--fg);box-shadow:var(--shadow)}
.btn-outline:hover{box-shadow:var(--shadow-hover)}
.btn-ghost{background:transparent;color:var(--fg)}
.btn-walnut{background:var(--accent);color:var(--accent-fg)}
.btn-full{width:100%}
.icon-btn{width:42px;height:42px;padding:0;border-radius:12px}
@media(max-width:639px){.desk-only{display:none!important}}
@media(min-width:1024px){.lg-hide{display:none!important}}
.hero{background:var(--hero);overflow:hidden}
.hero-grid{display:grid;gap:2.5rem;padding:3rem 0}
@media(min-width:1024px){.hero-grid{grid-template-columns:1.05fr .95fr;align-items:center;gap:3.5rem;padding:5rem 0}}
.kicker{font-size:.72rem;font-weight:500;letter-spacing:.18em;text-transform:uppercase;color:var(--muted);margin:0}
h1{font-family:var(--display);font-weight:500;letter-spacing:-.03em;font-size:clamp(2.1rem,6vw,3.6rem);line-height:1.1;margin:.75rem 0 0}
.lede{margin:1.25rem 0 0;max-width:28rem;color:var(--muted);font-size:1.05rem}
.cta-row{display:flex;flex-wrap:wrap;gap:.75rem;margin-top:2rem}
.fine{margin-top:1.25rem;font-size:.875rem;color:var(--subtle)}
.hero-art{position:relative}
.frame{background:var(--surface);padding:8px;border-radius:1.5rem;box-shadow:var(--shadow)}
.frame img{width:100%;border-radius:1rem;aspect-ratio:4/3;object-fit:cover}
.hero-float{display:none;position:absolute;bottom:-1.5rem;left:-.5rem;width:11rem;background:var(--surface);padding:6px;border-radius:1rem;box-shadow:var(--shadow)}
.hero-float img{aspect-ratio:4/3;border-radius:.75rem;object-fit:cover}
@media(min-width:640px){.hero-float{display:block}}
@media(min-width:1024px){.hero-float{left:-2rem}}
.facts{border-block:1px solid var(--border);background:var(--surface)}
.facts-grid{display:grid;gap:1px;background:var(--border)}
@media(min-width:640px){.facts-grid{grid-template-columns:repeat(3,1fr)}}
.facts article{background:var(--surface);padding:2rem 1.5rem}
.facts h2{font-family:var(--display);font-size:1.25rem;font-weight:500}
.facts p{margin:.5rem 0 0;color:var(--muted);font-size:.9rem}
section.block{padding:4rem 0}
section.alt{background:var(--hero)}
section.surface{background:var(--surface)}
.section-head{max-width:36rem}
.section-head h2{font-family:var(--display);font-size:clamp(1.8rem,4vw,2.4rem);font-weight:500;letter-spacing:-.03em;margin:.5rem 0 0}
.section-head p{margin:.75rem 0 0;color:var(--muted)}
.cards{display:grid;gap:1.25rem;margin-top:2.5rem}
@media(min-width:768px){.cards{grid-template-columns:repeat(3,1fr)}}
.card{display:flex;flex-direction:column;overflow:hidden;background:var(--surface);padding:8px;border-radius:1.5rem;box-shadow:var(--shadow)}
.card img{aspect-ratio:4/3;object-fit:cover;border-radius:1rem;width:100%}
.card-body{display:flex;flex-direction:column;flex:1;padding:1rem .75rem .75rem}
.badge{display:inline-flex;align-self:flex-start;font-size:.7rem;letter-spacing:.04em;text-transform:uppercase;color:var(--muted);background:var(--surface-muted);padding:.2rem .55rem;border-radius:999px}
.card h3{font-family:var(--display);font-size:1.5rem;font-weight:500;margin:.75rem 0 0}
.card p{margin:.5rem 0 0;color:var(--muted);font-size:.9rem;flex:1}
.suited{margin:.75rem 0 0;font-size:.75rem;color:var(--subtle)}
.card .btn{margin-top:1.25rem}
.craft-grid{display:grid;gap:2.5rem;align-items:center}
@media(min-width:1024px){.craft-grid{grid-template-columns:1fr 1fr;gap:4rem}}
.pips{display:grid;gap:.75rem;margin-top:2rem}
@media(min-width:640px){.pips{grid-template-columns:1fr 1fr}}
.pips li{list-style:none;background:var(--surface);padding:.85rem 1rem;border-radius:.85rem;box-shadow:var(--shadow);font-size:.9rem}
.pips{padding:0;margin-left:0}
.gallery{display:grid;gap:1rem;margin-top:2rem}
@media(min-width:640px){.gallery{grid-template-columns:repeat(3,1fr)}}
.shot{background:var(--surface);padding:8px;border-radius:1.5rem;box-shadow:var(--shadow);border:0;text-align:left;width:100%;font:inherit;color:inherit}
.shot img{width:100%;aspect-ratio:4/5;object-fit:cover;border-radius:1rem}
.shot span{display:flex;justify-content:space-between;padding:.75rem .5rem .25rem;font-size:.9rem;color:var(--muted)}
.order-grid{display:grid;gap:2.5rem}
@media(min-width:1024px){.order-grid{grid-template-columns:.9fr 1.1fr}}
.contact-chip{display:flex;align-items:center;justify-content:space-between;background:var(--bg);padding:.85rem 1rem;border-radius:1rem;box-shadow:var(--shadow);text-decoration:none;margin-top:.75rem}
.contact-chip small{display:block;color:var(--subtle);font-size:.75rem}
.form{background:var(--bg);padding:1.25rem;border-radius:1.5rem;box-shadow:var(--shadow)}
@media(min-width:640px){.form{padding:1.75rem}}
label,legend{font-size:.875rem;font-weight:500}
.field{display:grid;gap:.4rem;margin-top:1.1rem}
.row2{display:grid;gap:1.1rem}
@media(min-width:640px){.row2{grid-template-columns:1fr 1fr}}
input[type=text],input[type=tel],input[type=number],textarea{
  width:100%;border:0;border-radius:.85rem;background:var(--surface);padding:.85rem 1rem;
  font:inherit;color:var(--fg);box-shadow:var(--shadow);outline:none
}
input:focus,textarea:focus{box-shadow:var(--shadow-hover);outline:2px solid var(--primary);outline-offset:1px}
.packs{display:grid;gap:.5rem;margin-top:.5rem}
@media(min-width:640px){.packs{grid-template-columns:repeat(3,1fr)}}
.pack{cursor:pointer;background:var(--surface);padding:.85rem;border-radius:1rem;box-shadow:var(--shadow)}
.pack input{position:absolute;opacity:0;pointer-events:none}
.pack.selected{outline:2px solid var(--primary)}
.pack strong{display:block}
.pack em{font-style:normal;font-size:.75rem;color:var(--muted)}
.qty{display:flex;align-items:center;gap:.5rem}
.qty input{width:4.5rem;text-align:center;font-variant-numeric:tabular-nums}
.form-actions{display:flex;flex-direction:column;gap:.5rem;margin-top:1.5rem}
@media(min-width:640px){.form-actions{flex-direction:row}}
.form-actions .btn{flex:1}
footer.site{background:var(--accent);color:var(--accent-fg);margin-top:0}
.foot-inner{display:flex;flex-direction:column;gap:2rem;padding:3rem 0}
@media(min-width:768px){.foot-inner{flex-direction:row;justify-content:space-between}}
.foot-brand{display:flex;gap:.75rem;align-items:flex-start}
.foot-brand img{width:44px;height:44px;border-radius:8px;object-fit:cover}
.foot-brand p{margin:.35rem 0 0;max-width:16rem;color:color-mix(in srgb,var(--accent-fg) 70%,transparent);font-size:.9rem}
.foot-links{display:grid;gap:.35rem;font-size:.9rem}
.foot-links a,.foot-links button{background:none;border:0;color:inherit;padding:0;text-align:left;text-decoration:none}
.foot-links a:hover,.foot-links button:hover{text-decoration:underline}
.legal{border-top:1px solid color-mix(in srgb,var(--accent-fg) 10%,transparent);padding:1.1rem 0 1.4rem;font-size:.75rem;color:color-mix(in srgb,var(--accent-fg) 55%,transparent)}
.dock{position:fixed;inset-inline:0;bottom:0;z-index:30;border-top:1px solid var(--border);background:color-mix(in srgb,var(--bg) 95%,transparent);backdrop-filter:blur(10px);padding:.75rem .75rem max(.75rem,env(safe-area-inset-bottom));display:grid;grid-template-columns:1fr 1fr 1fr;gap:.5rem}
@media(min-width:640px){.dock,.dock-spacer{display:none}}
.dock-spacer{height:5rem}
.modal{position:fixed;inset:0;z-index:60;display:none;place-items:center;padding:1rem;background:rgba(28,22,16,.45)}
.modal.open{display:grid}
.modal-card{width:min(28rem,100%);background:var(--surface);border-radius:1.25rem;padding:1.25rem;box-shadow:var(--shadow);position:relative}
.modal-card.wide{width:min(40rem,100%);padding:.75rem}
.modal-card h2{font-family:var(--display);font-size:1.35rem;font-weight:500;padding-right:2rem}
.modal-card p{color:var(--muted);font-size:.9rem}
.close{position:absolute;top:.7rem;right:.7rem;width:36px;height:36px;border:0;border-radius:999px;background:var(--surface-muted);font-size:1.2rem;line-height:1}
.qr-wrap{background:var(--bg);border-radius:1rem;padding:1rem;margin:1rem 0}
.qr-wrap img{width:min(220px,100%);margin:auto;background:var(--surface);padding:8px;border-radius:.6rem}
.drawer{position:fixed;inset:0;z-index:50;display:none}
.drawer.open{display:block}
.drawer-panel{position:absolute;top:0;right:0;height:100%;width:min(20rem,90vw);background:var(--surface);padding:1.25rem;display:flex;flex-direction:column;gap:.25rem;box-shadow:var(--shadow)}
.drawer nav a{display:block;padding:.85rem .75rem;border-radius:.85rem;text-decoration:none}
.drawer nav a:hover{background:var(--surface-muted)}
.drawer .btn{margin-top:.4rem}
.backdrop{position:absolute;inset:0;background:rgba(28,22,16,.35);border:0;width:100%;height:100%}
@keyframes rise{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
.rise{animation:rise .4s cubic-bezier(.22,1,.36,1) both}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
#navbar,#navbar-iframe,.navbar,.blog-pager,.post-footer,#comments,.footer-outer,.sidebar-wrapper,.header-outer,.tabs-outer,#page,.Attribution,#Attribution1,body#layout #content{display:none!important}
.content-outer,.content-inner,.main-inner,.region-inner{width:auto!important;max-width:none!important;min-width:0!important;padding:0!important;margin:0!important;background:transparent!important;box-shadow:none!important}

body.script:
//

(function () {
  var PACKS = { snack: "Snack bag", party: "Party pack", bulk: "Bulk order" };
  var CTRL = /[\u0000-\u001F\u007F]/g;
  function sanitize(value, max) {
    return String(value || "").replace(CTRL, "").replace(/\s+/g, " ").trim().slice(0, max);
  }
  function clampQty(n) {
    n = Number(n);
    if (!isFinite(n)) return 1;
    return Math.min(99, Math.max(1, Math.floor(n)));
  }
  function orderLines() {
    var pack = (document.querySelector("input[name=pack]:checked") || {}).value || "snack";
    var qty = clampQty((document.getElementById("qty") || {}).value);
    var name = sanitize((document.getElementById("name") || {}).value, 80) || "—";
    var phone = sanitize((document.getElementById("phone") || {}).value, 24) || "—";
    var note = sanitize((document.getElementById("note") || {}).value, 200);
    var lines = [
      "Namaste, I would like to order Corn Puff Pipes from Acharya Dhunro Pasal.",
      "Name: " + name,
      "Phone: " + phone,
      "Pack: " + (PACKS[pack] || "Snack bag"),
      "Quantity: " + qty
    ];
    if (note) lines.push("Note: " + note);
    return { pack: PACKS[pack] || "Snack bag", lines: lines };
  }
  function openModal(id) {
    var el = document.getElementById(id);
    if (el) el.classList.add("open");
  }
  function closeModal(id) {
    var el = document.getElementById(id);
    if (el) el.classList.remove("open");
  }
  document.addEventListener("click", function (e) {
    var t = e.target.closest("[data-open],[data-close],[data-qty],[data-pack],[data-shot]");
    if (!t) return;
    if (t.hasAttribute("data-open")) openModal(t.getAttribute("data-open"));
    if (t.hasAttribute("data-close")) closeModal(t.getAttribute("data-close"));
    if (t.hasAttribute("data-qty")) {
      var input = document.getElementById("qty");
      if (input) input.value = clampQty(Number(input.value) + Number(t.getAttribute("data-qty")));
    }
    if (t.hasAttribute("data-pack")) {
      var id = t.getAttribute("data-pack");
      var radio = document.querySelector("input[name=pack][value='" + id + "']");
      if (radio) radio.checked = true;
      syncPacks();
      var order = document.getElementById("order");
      if (order) order.scrollIntoView({ behavior: "smooth" });
    }
    if (t.hasAttribute("data-shot")) {
      document.getElementById("lb-title").textContent = t.getAttribute("data-caption") || "";
      document.getElementById("lb-desc").textContent = t.getAttribute("data-alt") || "";
      var img = document.getElementById("lb-img");
      img.src = t.getAttribute("data-src");
      img.alt = t.getAttribute("data-alt") || "";
      openModal("lightbox");
    }
  });
  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape") {
      closeModal("pay");
      closeModal("lightbox");
      closeModal("menu");
    }
  });
  function syncPacks() {
    document.querySelectorAll(".pack").forEach(function (el) {
      var on = el.querySelector("input").checked;
      el.classList.toggle("selected", on);
    });
  }
  document.querySelectorAll("input[name=pack]").forEach(function (el) {
    el.addEventListener("change", syncPacks);
  });
  var form = document.getElementById("order-form");
  var email = document.getElementById("email-order");
  function refreshMailto() {
    var o = orderLines();
    var subject = "Corn Puff Pipes order — " + o.pack;
    var body = "Namaste,\n\n" + o.lines.slice(1).join("\n");
    email.href = "mailto:roms7291@gmail.com?subject=" + encodeURIComponent(subject) + "&body=" + encodeURIComponent(body);
  }
  ["input", "change"].forEach(function (ev) {
    form.addEventListener(ev, refreshMailto);
  });
  form.addEventListener("submit", function (e) {
    e.preventDefault();
    var o = orderLines();
    window.open("https://wa.me/9779845044572?text=" + encodeURIComponent(o.lines.join("\n")), "_blank", "noopener,noreferrer");
  });
  refreshMailto();
})();

//
